```jsx
import React, { useContext } from 'react';
import ThemeContext from './ThemeContext';

function ThemedButton() {
  const theme = useContext(ThemeContext);
  return <button style={{ background: theme === 'dark' ? '#333' : '#fff' }}>Click me</button>;
}
```

```jsx
function Button({ onClick, children, type = 'button', disabled = false }) {
  return (
    <button type={type} onClick={onClick} disabled={disabled}>
      {children}
    </button>
  );
}
```

```jsx
function Input({ value, onChange, placeholder, type = 'text' }) {
  return <input value={value} onChange={onChange} placeholder={placeholder} type={type} />;
}
```

